def rle_decode(s: str) -> str:
    result = ""
    current_char = ""
    for char in s:
        if char.isdigit():
            if current_char.isdigit():
                result += current_char
            else:
                result += current_char + str(int(current_char) + 1)
                current_char = ""
        else:
            current_char += char
    result += current_char
    return result

def char_frequency(s: str) -> dict[str, int]:
    """
    Returns a dictionary mapping each character in s to the number of times it appears.

    The function is case-sensitive and counts spaces.

    Parameters:
    s (str): The input string.

    Returns:
    dict[str, int]: A dictionary where each key is a character in s and each value is the frequency of that character.
    """
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

