def roman_to_int(s: str) -> int:
    """
    Convert a valid uppercase Roman numeral (1 to 3999, using subtractive notation such as IV and CM) to an integer.

    :param s: A string representing a valid Roman numeral.
    :return: The integer value of the Roman numeral.
    """
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900
    }

    i = 0
    result = 0

    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in roman_map:
            result += roman_map[s[i:i+2]]
            i += 2
        elif s[i] in roman_map:
            result += roman_map[s[i]]
            i += 1
        else:
            raise ValueError("Invalid Roman numeral")

    return result

from typing import List

def group_anagrams(words: List[str]) -> List[List[str]]:
    anagrams = {}
    for word in words:
        sorted_word = "".join(sorted(word))
        if sorted_word in anagrams:
            anagrams[sorted_word].append(word)
        else:
            anagrams[sorted_word] = [word]

    result = []
    for group in anagrams.values():
        # Sort the words in each group
        group.sort()
        result.append(group)

    # Sort the groups by their first word
    result.sort(key=lambda group: group[0])

    return result

