def evaluate(expr: str) -> int:
    def apply_op():
        op = ops.pop()
        right = vals.pop()
        left = vals.pop()
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            return left // right

    expr = expr.replace(" ", "")
    vals = []
    ops = []
    for c in expr:
        if c.isdigit():
            vals.append(int(c))
        elif c in ['+', '-', '*', '/']:
            while ops and ops[-1] != '(' and get_precedence(ops[-1]) >= get_precedence(c):
                vals.append(apply_op())
            ops.append(c)
        elif c == '(':
            ops.append(c)
        elif c == ')':
            while ops[-1] != '(':
                vals.append(apply_op())
            ops.pop()
            if ops and ops[-1] == '(':
                ops.pop()
    while ops:
        vals.append(apply_op())
    return vals[0]

def get_precedence(op):
    if op in ['+', '-']:
        return 1
    elif op in ['*', '/']:
        return 2
    else:
        return 0

